modelCode:
function model(p) {
  // Teams adopt a new way of working in a staggered rollout. Each team's cycle time (days from start to done) is measured
  // before and after; the true improvement is the effect size, measurements are noisy, and a mean of n measurements
  // carries a standard error. Numbers are seeded and illustrative.
  const effect = Math.max(0, Math.min(40, Math.round(p.effect / 5) * 5));
  const n = Math.max(5, Math.min(60, Math.round(p.sampleSize / 5) * 5));
  const teams = Math.max(4, Math.min(12, Math.round(p.teams)));
  let seed = 7 + teams * 131;
  const rnd = () => { seed |= 0; seed = seed + 0x6D2B79F5 | 0; let t = Math.imul(seed ^ seed >>> 15, 1 | seed); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; };
  const gauss = () => { const u = Math.max(1e-9, rnd()), v = rnd(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v); };
  const NAMES = ['Atlas', 'Birch', 'Cedar', 'Delta', 'Ember', 'Falcon', 'Granite', 'Harbor', 'Indigo', 'Juniper', 'Kestrel', 'Lumen'];
  const CV = 0.25, Z = 1.96, ROLLOUT = 6, MONTHS = 12;
  const ramp = k => k < 0 ? 0 : k === 0 ? 0.5 : 1; // half the effect in the adoption month, full from the next
  // Noise per team is fixed in its own seed stream so that changing the effect or n does not reshuffle the teams
  const list = Array.from({ length: teams }, (_, i) => {
    const baseline = +(8 + 8 * rnd()).toFixed(1), trueEffect = Math.max(0, effect + 4 * gauss()); // some teams gain more than others
    const zB = gauss(), zA = gauss(), zM = Array.from({ length: MONTHS + 1 }, () => gauss());
    return { i, name: NAMES[i], baseline, trueEffect: +trueEffect.toFixed(1), adopt: 1 + Math.floor(i * ROLLOUT / teams), zB, zA, zM };
  });
  list.forEach(t => {
    const sd = CV * t.baseline, se = sd / Math.sqrt(n);
    t.before = +(t.baseline + se * t.zB).toFixed(2);
    t.after = +(t.baseline * (1 - t.trueEffect / 100) + se * t.zA).toFixed(2);
    t.se = +se.toFixed(3);
    t.change = +(100 * (t.after - t.before) / t.before).toFixed(1);
    t.margin = +(100 * Z * Math.sqrt(2) * se / t.before).toFixed(1);
    t.lo = +(t.change - t.margin).toFixed(1); t.hi = +(t.change + t.margin).toFixed(1);
    t.clear = t.hi < 0; // the range excludes zero: a real improvement at 95 %
    t.looksWorse = t.change > 0;
    // Monthly series for the cohort view: months 1..12 of the rollout
    t.months = Array.from({ length: MONTHS }, (_, m) => { const month = m + 1, k = month - t.adopt, v = t.baseline * (1 - ramp(k) * t.trueEffect / 100) + se * t.zM[m]; return { month, k, value: +v.toFixed(2), pct: +(100 * (v - t.baseline) / t.baseline).toFixed(1) }; });
  });
  const sumB = list.reduce((a, t) => a + t.before, 0), sumA = list.reduce((a, t) => a + t.after, 0);
  const pooled = +(100 * (sumA - sumB) / sumB).toFixed(1);
  const pooledMargin = +(100 * Z * Math.sqrt(list.reduce((a, t) => a + 2 * t.se * t.se, 0)) / sumB).toFixed(1);
  // Cohorts: teams by adoption month; cells are the mean % change against baseline by months since adoption (-2 to 5)
  const KS = [-2, -1, 0, 1, 2, 3, 4, 5];
  const cohorts = Array.from({ length: ROLLOUT }, (_, c) => { const month = c + 1, members = list.filter(t => t.adopt === month);
    const cells = KS.map(k => { const vals = members.map(t => t.months.find(x => x.k === k)).filter(x => x && x.month >= 1 && x.month <= MONTHS).map(x => x.pct);
      return { k, month: month + k, n: vals.length, pct: vals.length ? +(vals.reduce((a, v) => a + v, 0) / vals.length).toFixed(1) : null }; });
    return { month, label: 'M' + month, teams: members.map(t => t.name), size: members.length, cells }; }).filter(c => c.size > 0);
  const clearCount = list.filter(t => t.clear).length, worseCount = list.filter(t => t.looksWorse).length;
  const sorted = list.slice().sort((a, b) => a.change - b.change).map(t => t.i);
  const steps = [
    { id: 'before', t: 0, title: 'Before: ' + teams + ' teams, one baseline each', note: 'Cycle time per team before the rollout, each a mean of ' + n + ' measurements. Teams differ more than any method will change them.' },
    { id: 'after', t: 4.5, title: 'After: the slopes', note: 'The same teams after adopting the method. Pooled change ' + pooled + ' %' + (worseCount ? '; ' + worseCount + (worseCount === 1 ? ' team looks worse' : ' teams look worse') + ', which is the noise talking.' : '; every team moved the same way.') },
    { id: 'ranges', t: 9.5, title: 'The ranges', note: 'Each change carries a 95 % range of ± ' + (list.reduce((a, t) => a + t.margin, 0) / teams).toFixed(0) + ' points at n = ' + n + '. ' + clearCount + ' of ' + teams + ' teams clear zero on their own; the pooled change is ' + pooled + ' % ± ' + pooledMargin + '.' },
    { id: 'cohorts', t: 14.5, title: 'Cohorts: the rollout, month by month', note: 'Teams adopted over ' + ROLLOUT + ' months. Lining them up by months since adoption shows the same step in every cohort, which one before-and-after pair cannot.' },
    { id: 'sowhat', t: 18.5, title: 'So what for the story', note: 'Lead with the pooled change and its range, show the slope for every team, and let the cohort grid answer "was it just one good team?"' }
  ];
  const summary = 'Pooled change ' + pooled + ' % (± ' + pooledMargin + ') across ' + teams + ' teams at n = ' + n + '; ' + clearCount + ' teams clear zero on their own, ' + worseCount + ' look worse by chance.';
  return { effect, n, teams, rollout: ROLLOUT, monthsTotal: MONTHS, list, sorted, pooled, pooledMargin, clearCount, worseCount, cohorts, ks: KS, steps, duration: 21, markers: steps.map(s => s.t), summary };
}

checkCode:
function check(p) {
  const m = model(p), Z = 1.96;
  // Each team's change, margin and flags follow from its before and after means
  const perTeam = m.list.every(t => Math.abs(t.change - 100 * (t.after - t.before) / t.before) < 0.06
    && Math.abs(t.margin - 100 * Z * Math.sqrt(2) * t.se / t.before) < 0.06 && t.clear === (t.hi < 0) && t.looksWorse === (t.change > 0) && Math.abs(t.hi - t.lo - 2 * t.margin) < 0.11);
  // Margins shrink with the square root of the sample size: se * sqrt(n) is the fixed measurement spread
  const seOk = m.list.every(t => Math.abs(t.se * Math.sqrt(m.n) - 0.25 * t.baseline) < 0.01);
  // The pooled change sits within three of its own margins of the stated effect (the noise is seeded, the effect is the signal)
  const pooledOk = Math.abs(m.pooled + m.effect) <= Math.max(3 * m.pooledMargin, 6);
  // Cohorts: every team belongs to one cohort in the rollout window, and cells before adoption average near zero
  const sizes = m.cohorts.reduce((a, c) => a + c.size, 0);
  const adoptOk = sizes === m.teams && m.list.every(t => t.adopt >= 1 && t.adopt <= m.rollout);
  const preCells = m.cohorts.flatMap(c => c.cells.filter(x => x.k < 0 && x.pct !== null).map(x => x.pct));
  const preOk = preCells.length === 0 || Math.abs(preCells.reduce((a, v) => a + v, 0) / preCells.length) < 12;
  const postCells = m.cohorts.flatMap(c => c.cells.filter(x => x.k >= 1 && x.pct !== null).map(x => x.pct));
  const postOk = m.effect === 0 || postCells.reduce((a, v) => a + v, 0) / postCells.length < 0;
  const pass = perTeam && seOk && pooledOk && adoptOk && preOk && postOk;
  return {
    pass,
    detail: 'Pooled change ' + m.pooled + ' % ± ' + m.pooledMargin + ' against a stated effect of −' + m.effect + ' %' + (pooledOk ? '' : ' (too far apart)') + '; ' + m.clearCount + ' of ' + m.teams + ' teams clear zero; margins scale with 1/√n' + (seOk ? '' : ' (they do not)') +
      '; ' + m.cohorts.length + ' cohorts hold all ' + m.teams + ' teams' + (adoptOk ? '' : ' (mismatch)') + '; pre-adoption cells average ' + (preCells.length ? (preCells.reduce((a, v) => a + v, 0) / preCells.length).toFixed(1) : '0') + ' %.'
  };
}
